      fieldType:    FieldType.TEXTAREA,
      isRequired:   true,
      isAutoFilled: false,
      sortOrder:    6,
      defaultValue: 'El objetivo de una auditoría es la expresión de una opinión sobre la razonabilidad de los estados financieros en su conjunto. Nuestra auditoría será realizada de acuerdo con Normas Internacionales de Auditoría (NIAs). Dichas Normas requieren que planifiquemos, y realicemos la auditoría a fin de obtener una seguridad razonable y que los estados financieros están exentos de errores significativos. Una auditoría incluye el examen, en base a pruebas, de la evidencia que respalda los montos y la información expuesta en los estados financieros, la determinación de la base contable utilizada y las estimaciones significativas efectuadas por la Administración, y la evaluación de la presentación general en los estados financieros.',
