      fieldType:    FieldType.TEXTAREA,
      isRequired:   true,
      isAutoFilled: false,
      sortOrder:    8,
      defaultValue: 'La administración es responsable de salvaguardar los activos de la sociedad y de la prevención y detección de fraudes y errores. También es responsable por identificar y asegurar que la Administración cumpla con las leyes y reglamentaciones aplicables a sus actividades. No obstante, procuraremos planificar nuestra auditoría de manera de tener una expectativa razonable de detectar errores significativos en los estados financieros o registros contables (incluyendo cualquier error, fraude o incumplimiento de leyes o reglamentaciones que sea significativo), pero no se deberá depositar confianza en que nuestro examen revelará todos los errores, fraudes o casos de incumplimiento significativos que pudieran existir.\n\nNuestra auditoría no incluirá un examen detallado de las transacciones, como el que sería necesario para revelar errores o fraudes que no causaron un error significativo en los estados financieros. Es importante reconocer que existen limitaciones inherentes en el proceso de auditoría. Las auditorías están basadas en el concepto de pruebas selectivas de los datos en los que se basan los estados financieros, que involucra el ejercicio del criterio con respecto a las áreas que se probarán y la naturaleza, oportunidad, alcance y resultados de las pruebas a ser realizadas.\n\nPor consiguiente, las auditorías están sujetas a la limitación de que puedan no detectarse errores significativos, fraudes u otros actos ilegales con un impacto directo y significativo en los estados financieros, en caso de existir. Debido a las características del fraude, en particular aquellos que involucran encubrimiento mediante confabulación y documentación falsificada, una auditoría diseñada y llevada a cabo de acuerdo con Normas Internacionales de Auditoría podría no detectar un fraude significativo. Por otra parte, si bien un control interno efectivo reduce la probabilidad de que ocurran y no se detecten errores, fraudes u otros actos ilegales, no elimina esa posibilidad. Por estos motivos no puedo asegurar que se detectarán errores, fraudes u otros actos ilegales, en caso de existir. Sin embargo, les comunicaremos cualquier acto ilegal, error significativo o evidencia de que puede existir un fraude, identificado en el curso de nuestra auditoría.',
