      fieldType:    FieldType.MATRIX,
      isRequired:   true,
      isAutoFilled: false,
      sortOrder:    3,
      aiHint:       'Columnas: # Deficiencia | Fecha comunicación | Forma (Oral/Escrita/Esta carta) | Persona notificada (cargo) | ¿Acuse de recibo? | Respuesta de administración | Plan de acción comprometido. NIA 265.9: el auditor debe comunicar oportunamente las deficiencias de CI a la administración, independientemente de su severidad. "Oportunamente" significa que la comunicación permita a la administración tomar acciones correctivas antes de que la entidad emita sus EEFF. Las deficiencias menores pueden comunicarse verbalmente, pero las significativas y materiales deben ser por escrito.',
