      aiHint:       'Completar SOLO si hay deficiencias significativas o materiales. NIA 265.10: el auditor debe comunicar por escrito al TCWG las deficiencias significativas identificadas durante la auditoría. Documente: (1) Fecha de la comunicación escrita. (2) Destinatarios (presidente de Junta / Comité de Auditoría). (3) Lista de deficiencias significativas comunicadas (referencia a S1). (4) Si se comunicó también a la administración. (5) Confirmación de que el TCWG entendió la naturaleza y gravedad de cada deficiencia. Esta comunicación se vincula también con D-05 S4 (Comunicación TCWG).',
