      aiHint:       'NIA 610.32: antes de usar el trabajo de AI, el auditor externo debe: (1) Re-ejecutar algunos procedimientos de AI sobre los mismos ítems (re-performance): porcentaje típico 5-15% de la muestra. (2) Revisar los papeles de trabajo de AI de las áreas seleccionadas en S2: ¿documentación suficiente? ¿conclusiones consistentes con la evidencia? (3) Determinar si las conclusiones de AI son consistentes con los resultados del auditor externo. Si se detecta que los PT de AI tienen deficiencias o que las conclusiones no están soportadas: ampliar los procedimientos propios y reconsiderar si se puede usar el trabajo de AI en esa área.',
