      fieldType:    FieldType.MATRIX,
      isRequired:   true,
      isAutoFilled: false,
      sortOrder:    7,
      aiHint:       'Columnas: Criterio | Evaluación (Sí / No / N/A) | Evidencia revisada | Observaciones. OBJETIVIDAD (NIA 610.15-17): (1) AI tiene acceso directo al Comité de Auditoría o Junta Directiva. (2) Puede comunicarse sin interferencia de la dirección operativa. (3) No depende exclusivamente del área auditada. (4) Tiene autoridad para realizar sus trabajos sin restricciones. (5) No participa en operaciones que posteriormente audita. (6) No diseña controles que posteriormente evalúa. (7) No tiene responsabilidades operativas incompatibles. (8) Puede reportar hallazgos sin presión de la dirección. COMPETENCIA (NIA 610.18-20): (9) Formación profesional del equipo (CIA, CPA, CISA, equivalentes). (10) Experiencia técnica en el sector y áreas auditadas. (11) Capacitación continua documentada. (12) El equipo de AI es suficiente en número para el alcance del plan. METODOLOGÍA Y ENFOQUE SISTEMÁTICO (NIA 610.21-23): (13) Existe estatuto/carta de AI aprobada por el gobierno corporativo. (14) Existe plan anual de AI basado en riesgos. (15) Los trabajos siguen metodología documentada (IIA Standards 2024 o equivalente). (16) Los papeles de trabajo son suficientes para soportar conclusiones. (17) Existe proceso de seguimiento de hallazgos y recomendaciones. (18) La función realiza autoevaluaciones de calidad o revisiones externas. CALIDAD DEL TRABAJO (NIA 610.24): (19) Los informes emitidos están bien estructurados y son claros. (20) Las conclusiones son consistentes con la evidencia. (21) Los procedimientos aplicados son adecuados para el objetivo de cada trabajo.',
