      isRequired:   true,
      isAutoFilled: false,
      sortOrder:    3,
      aiHint:       'Columnas: Tipo de amenaza | Aplicable (Sí/No) | Persona(s) afectada(s) | Descripción específica | Salvaguarda aplicada | ¿Subsiste amenaza? (Sí/No). Amenazas IESBA a verificar: (1) INTERÉS PROPIO: participación accionaria, crédito/préstamo del cliente, honorarios contingentes, cuotas atrasadas significativas. (2) AUTORREVISIÓN: prestación de servicios de contabilidad, valoración, diseño de SI/TI para el cliente — documentar en S9. (3) ABOGACÍA: representar al cliente en litigio o actuar como promotor ante regulador. (4) FAMILIARIDAD: familiar cercano en posición que influye en EEFF, ex-socio ahora en el cliente, relación personal cercana con administración. (5) INTIMIDACIÓN: presión del cliente sobre la opinión, amenaza de sustitución por desacuerdo, presión para emitir opinión sin reservas. (6) ROTACIÓN: socio en encargo >7 años (IESBA) o verificar plazo CVPCPA vigente. Para cada amenaza identificada con "Sí": describir detalle y salvaguarda; consolidar en S5.',
