      aiHint:       'Columnas: N° | Descripción del servicio | Prestado por (nombre / área) | Período | Honorarios ($) | Tipo de amenaza (Autorrevisión / Abogacía / Interés propio / Otra) | Nivel de amenaza (Alto / Medio / Bajo / Ninguno) | Salvaguarda aplicada | Compatible con independencia (Sí / No). Servicios que generan amenaza de AUTORREVISIÓN — evaluar con especial cuidado: llevar contabilidad o registros del cliente, elaborar EEFF o notas, realizar valoraciones incluidas en EEFF auditados, diseñar o implementar sistemas contables/ERP, procesar nómina. Servicios que generan amenaza de ABOGACÍA: representación legal ante tribunales o reguladores, actuación como promotor en transacciones. Si el nivel de amenaza es ALTO y no existe salvaguarda suficiente: el servicio debe rechazarse o descontinuarse antes de aceptar el encargo de auditoría. Si no existen servicios distintos de auditoría: registrar una fila con "Ningún servicio non-audit prestado al cliente durante el período". Conclusión: Los servicios identificados [ ] son / [ ] no son compatibles con la independencia requerida.',
