      isRequired:   false,
      isAutoFilled: false,
      sortOrder:    4,
      aiHint:       'Columnas: Área | N° ítems examinados | Errores encontrados ($) | Tasa de error (%) | Error proyectado al universo ($) | ¿Supera UAE? | ¿Supera ME? | ¿Supera MG? | Acción. Proyección MUS: Error proyectado = (Error encontrado / Tamaño muestra) × Universo. Si error proyectado > ME: ampliar muestra o proponer AJE. Si error proyectado > MG: evaluar modificación de opinión. Columna "Acción": Ninguna / Ampliar muestra / Proponer AJE / Comunicar a socio / Modificar opinión.',
